// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  interpolate,
  Easing,
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
} from '../remotionShim';


export type SteelGateTransitionProps = Record<string, any>;

const GateHalf: React.FC<{
  side: "left" | "right";
  color: string;
  offset: number;
  width: number;
  height: number;
  barOpacity: number;
}> = ({ side, color, offset, width, height, barOpacity }) => {
  const isLeft = side === "left";

  return (
    <div
      style={{
        position: "absolute",
        width: "50%",
        height: "100%",
        backgroundColor: color,
        left: isLeft ? 0 : "auto",
        right: isLeft ? "auto" : 0,
        transform: `translateX(${isLeft ? offset : -offset}px)`,
        // Using standard CSS background for gradients to ensure zero network loading issues
        background: `linear-gradient(${
          isLeft ? "90deg" : "-90deg"
        }, rgba(255,255,255,0.08) 0%, rgba(0,0,0,0.35) 85%, rgba(0,0,0,0.7) 100%)`,
        borderRight: isLeft ? "16px solid #111" : "none",
        borderLeft: !isLeft ? "16px solid #111" : "none",
        display: "flex",
        flexDirection: "column",
        justifyContent: "space-evenly",
        alignItems: isLeft ? "flex-end" : "flex-start",
        padding: "0 30px",
        boxSizing: "border-box",
        boxShadow: isLeft
          ? "30px 0 60px rgba(0,0,0,0.6)"
          : "-30px 0 60px rgba(0,0,0,0.6)",
        transition: "none",
      }}
    >
      {[1, 2, 3, 4].map((i) => (
        <div
          key={i}
          style={{
            width: "100%",
            height: height * 0.08,
            backgroundColor: `rgba(0,0,0,${barOpacity})`,
            borderTop: "2px solid rgba(255,255,255,0.15)",
            borderBottom: "6px solid rgba(0,0,0,0.7)",
            position: "relative",
            borderRadius: "3px",
            boxShadow: "0 5px 15px rgba(0,0,0,0.3)",
            transition: "none",
          }}
        >
          {/* Outer Rivet */}
          <div
            style={{
              position: "absolute",
              [isLeft ? "right" : "left"]: "20px",
              top: "50%",
              transform: "translateY(-50%)",
              width: 22,
              height: 22,
              borderRadius: "50%",
              backgroundColor: "#3a3d42",
              boxShadow:
                "inset 2px 2px 5px rgba(255,255,255,0.4), 3px 3px 6px rgba(0,0,0,0.9)",
              transition: "none",
            }}
          />
          {/* Inner Rivet */}
          <div
            style={{
              position: "absolute",
              [isLeft ? "right" : "left"]: "70px",
              top: "50%",
              transform: "translateY(-50%)",
              width: 14,
              height: 14,
              borderRadius: "50%",
              backgroundColor: "#3a3d42",
              boxShadow:
                "inset 1px 1px 4px rgba(255,255,255,0.3), 2px 2px 5px rgba(0,0,0,0.9)",
              transition: "none",
            }}
          />
        </div>
      ))}
    </div>
  );
};

const SteelGateTransition: React.FC<SteelGateTransitionProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 2,
  gateColor = "#4a4e54",
  structuralBarOpacity = 0.4,
  finalBlackoutColor = "#000000",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const slamDurationInSeconds = 0.4;
  const holdDurationInSeconds = 0.15;
  const blackoutDurationInSeconds = 0.2;

  const slamFrames = Math.floor(fps * slamDurationInSeconds);
  const holdFrames = Math.floor(fps * holdDurationInSeconds);
  const blackoutFrames = Math.floor(fps * blackoutDurationInSeconds);
  
  const impactFrame = slamFrames;
  const blackoutStartFrame = impactFrame + holdFrames;

  // Gate Slam Interpolation
  // poly(5) easing creates a slow start that violently accelerates into a hard stop
  const slamProgress = interpolate(frame, [0, slamFrames], [0, 1], {
    easing: Easing.in(Easing.poly(5)),
    extrapolateRight: "clamp",
  });

  const gateOffset = interpolate(slamProgress, [0, 1], [-width / 2, 0]);
  
  // Slight scale-up for impact tension
  const scale = interpolate(slamProgress, [0, 1], [1, 1.05]);

  // Screen Shake upon impact
  const shakeX = interpolate(
    frame,
    [impactFrame, impactFrame + 2, impactFrame + 4, impactFrame + 6, impactFrame + 8],
    [0, width * 0.02, -width * 0.015, width * 0.005, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const shakeY = interpolate(
    frame,
    [impactFrame, impactFrame + 1, impactFrame + 3, impactFrame + 5, impactFrame + 7],
    [0, height * 0.02, -height * 0.015, height * 0.01, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Quick white flash simulating metal sparking/clashing
  const flashOpacity = interpolate(
    frame,
    [impactFrame, impactFrame + 2, impactFrame + 8],
    [0, 0.7, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Final rapid cut to black
  const blackoutOpacity = interpolate(
    frame,
    [blackoutStartFrame, blackoutStartFrame + blackoutFrames],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Container that handles the scale and shake impact */}
      <AbsoluteFill
        style={{
          transform: `translate(${shakeX}px, ${shakeY}px) scale(${scale})`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        <GateHalf
          side="left"
          color={gateColor}
          offset={gateOffset}
          width={width}
          height={height}
          barOpacity={structuralBarOpacity}
        />
        <GateHalf
          side="right"
          color={gateColor}
          offset={gateOffset}
          width={width}
          height={height}
          barOpacity={structuralBarOpacity}
        />
      </AbsoluteFill>

      {/* Impact Flash */}
      <AbsoluteFill
        style={{
          backgroundColor: "#ffffff",
          opacity: flashOpacity,
          transition: "none",
          mixBlendMode: "overlay"
        }}
      />

      {/* Final Blackout Cover */}
      <AbsoluteFill
        style={{
          backgroundColor: finalBlackoutColor,
          opacity: blackoutOpacity,
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default SteelGateTransition;